mapper.select:
SELECT INSTRUMENT_ID, INSTRUMENT_NO, BILL_NO, BILL_TYPE, BILL_AMOUNT, CURRENCY_CODE, DRAWER, DRAWER_ACCOUNT, PAYEE, PAYEE_ACCOUNT, ACCEPTOR, ACCEPTOR_ACCOUNT, ISSUE_DATE, MATURITY_DATE, BILL_STATUS, DELETE_FLAG, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_USER, UPDATE_USER FROM TBL_BILL_INSTRUMENT WHERE DELETE_FLAG = 0
AND INSTRUMENT_NO LIKE CONCAT('%', #{instrumentNumber}, '%')
AND BILL_TYPE = #{instrumentType}
AND BILL_STATUS = #{instrumentStatus}
AND DRAWER LIKE CONCAT('%', #{drawer}, '%')
AND PAYEE LIKE CONCAT('%', #{payee}, '%')
AND CREATE_TIME >= #{startDate}
AND CREATE_TIME <= #{endDate}
ORDER BY CREATE_TIME DESC

