WHERE INSTRUMENT_ID IN

    #{id}

mapper.select:
SELECT dateLabel, SUM(count) AS count, SUM(amount) AS amount FROM ( SELECT TO_CHAR(CREATE_TIME, 'MM/DD') AS dateLabel, TO_CHAR(CREATE_TIME, 'YYYY-MM-DD') AS sortDate, COUNT(*) AS count, COALESCE(SUM(BILL_AMOUNT), 0) AS amount FROM TBL_BILL_INSTRUMENT WHERE DELETE_FLAG = 0
AND CREATE_TIME >= #{startDate}
AND CREATE_TIME <= #{endDate}
GROUP BY TO_CHAR(CREATE_TIME, 'MM/DD'), TO_CHAR(CREATE_TIME, 'YYYY-MM-DD') UNION ALL SELECT TO_CHAR(CREATE_TIME, 'MM/DD') AS dateLabel, TO_CHAR(CREATE_TIME, 'YYYY-MM-DD') AS sortDate, COUNT(*) AS count, COALESCE(SUM(BILL_AMOUNT), 0) AS amount FROM TBL_BILL_REGISTRATION WHERE DELETE_FLAG = 0
AND CREATE_TIME >= #{startDate}
AND CREATE_TIME <= #{endDate}
GROUP BY TO_CHAR(CREATE_TIME, 'MM/DD'), TO_CHAR(CREATE_TIME, 'YYYY-MM-DD') ) combined GROUP BY dateLabel, sortDate ORDER BY sortDate ASC

SELECT category, SUM(count) AS count, SUM(amount) AS amount, AVG(avgAmount) AS avgAmount FROM ( SELECT
BILL_TYPE AS category,
BILL_STATUS AS category,
ACCEPTOR AS category,
BILL_TYPE AS category,
COUNT(*) AS count, COALESCE(SUM(BILL_AMOUNT), 0) AS amount, COALESCE(AVG(BILL_AMOUNT), 0) AS avgAmount FROM TBL_BILL_INSTRUMENT WHERE DELETE_FLAG = 0
AND CREATE_TIME >= #{startDate}
AND CREATE_TIME <= #{endDate}
AND BILL_TYPE IN
#{type}
AND BILL_STATUS IN
#{status}
GROUP BY
BILL_TYPE BILL_STATUS ACCEPTOR BILL_TYPE
UNION ALL SELECT
BILL_TYPE AS category,
BILL_STATUS AS category,
ACCEPTING_BANK AS category,
BILL_TYPE AS category,
COUNT(*) AS count, COALESCE(SUM(BILL_AMOUNT), 0) AS amount, COALESCE(AVG(BILL_AMOUNT), 0) AS avgAmount FROM TBL_BILL_REGISTRATION WHERE DELETE_FLAG = 0
AND CREATE_TIME >= #{startDate}
AND CREATE_TIME <= #{endDate}
AND BILL_TYPE IN
#{type}
AND BILL_STATUS IN
#{status}
GROUP BY
BILL_TYPE BILL_STATUS ACCEPTING_BANK BILL_TYPE
) combined GROUP BY category ORDER BY count DESC
